        except sqlite3.Error as e:
            raise RuntimeError(f"Failed to open database: {e}")

    def __enter__(self):
        return self

    def __exit__(self, exc_type, exc_value, traceback):
        if self.connection is not None:
            self.connection.close()

    def create_table(self):
