                            z10 * (xi - x[i]) * (y[j + 1] - yi) +
                            z01 * (x[i + 1] - xi) * (yi - y[j]) +
                            z11 * (xi - x[i]) * (yi - y[j])) / ((x[i + 1] - x[i]) * (y[j + 1] - y[j]));
                        z_interp.push_back(zi);
                        break;
                    }
                }
                break;
            }
        }
    }
    return z_interp;
}

