    std::regex re(pattern);
    std::sregex_token_iterator it(text.begin(), text.end(), re, -1);
    std::sregex_token_iterator reg_end;

    std::vector<std::string> result;
    for (; it != reg_end; ++it) {

        result.push_back(it->str());
    }


    if (text.empty()) {
        return result;
    }
    if (result[0] != text)
    {
        result.push_back("");
    }



    return result;
}

