import random
import re
from collections import defaultdict
from typing import List, Tuple, Dict, Optional, Union

class Calculator:
    def __init__(self):
        self.operators = {
            '+': lambda x, y: x + y,
            '-': lambda x, y: x - y,
            '*': lambda x, y: x * y,
            '/': lambda x, y: x / y,
            '^': lambda x, y: x ** y
        }

    def calculate(self, expression: str) -> float:
        if not expression:
            return 0.0

        tokens = re.findall(r'(\d*\.\d*|\d+|[+\-*/^()])', expression)
        if not tokens:
            return 0.0

        operand_stack = []
        operator_stack = []
        num_buffer = ''

        for ch in expression:
            if ch.isdigit() or ch == '.':
                num_buffer += ch
            else:
                if num_buffer:
                    operand_stack.append(float(num_buffer))
                    num_buffer = ''
                if ch in '+-*/^':
                    while operator_stack and operator_stack[-1] != '(' and self.precedence(operator_stack[-1]) >= self.precedence(ch):
                        operand_stack, operator_stack = self.apply_operator(operand_stack, operator_stack)
                    operator_stack.append(ch)
                elif ch == '(':
                    operator_stack.append(ch)
                elif ch == ')':
                    while operator_stack and operator_stack[-1] != '(':
                        operand_stack, operator_stack = self.apply_operator(operand_stack, operator_stack)
                    if operator_stack and operator_stack[-1] == '(':
                        operator_stack.pop()

        if num_buffer:
            operand_stack.append(float(num_buffer))

        while operator_stack:
            operand_stack, operator_stack = self.apply_operator(operand_stack, operator_stack)

        return operand_stack[-1] if operand_stack else 0.0

    def precedence(self, op: str) -> int:
        if op in '+-':
            return 1
        elif op in '*/':
            return 2
        elif op == '^':
            return 3
        return 0

    def apply_operator(self, operand_stack: List[float], operator_stack: List[str]) -> Tuple[List[float], List[str]]:
        if not operator_stack:
            return operand_stack, operator_stack

        op = operator_stack.pop()
        if len(operand_stack) < 2:
            raise ValueError("Invalid expression")

        operand2 = operand_stack.pop()
        operand1 = operand_stack.pop()

        result = self.operators[op](operand1, operand2)
        operand_stack.append(result)
        return operand_stack, operator_stack

class TwentyFourPointGame:
