class WeatherSystem:
    def __init__(self, city):
        self.city = city
        self.temperature = 0.0
        self.weather = ""
        self.weather_list = {}

    def query(self, weather_list, tmp_units="celsius"):
        self.weather_list = weather_list.copy()
        if self.city not in self.weather_list:
