                String insertQuery = String.format(
                        "INSERT INTO %s (name, age) VALUES ('%s', %d)",
                        tableName, item.get("name"), (int) item.get("age"));
                stmt.execute(insertQuery);
            }
        } catch (SQLException e) {
            e.printStackTrace();
        }
