            raise ValueError("the input must be a tuple([0,...,1,...],int) or a iteration of list of tuple")
        separate_results = []
        for item in data:
            sub_list = item.get_list()
            total_num = item.get_total_num()
            if total_num == 0:
                separate_results.append(0.0)
            else:
