        total_value = 0;
        for (const auto& item : cart.getProducts()) {
            total_value += item.getQuantity() * item.getPrice();
        }
    }

public:
    DiscountStrategy(const Customer& customer, const Cart& cart, const Promotion& promotion = nullptr)
        : customer(customer), cart(cart), promotion(promotion) {
        updateTotal();
    }

    double total() const {
        updateTotal();
        return total_value;
    }

    double due() const {
        double discount = (promotion == nullptr) ? 0 : promotion(*this);
        return total_value - discount;
    }

    double promotion() const {
        double discount = (promotion == nullptr) ? 0 : promotion(*this);
        return discount;
    }

    const Customer& customer() const { return customer; }
    const Cart& cart() const { return cart; }
};
```

### Explanation
1. **Product Class**: Represents items in the cart with name, quantity, and price. Provides getters for these attributes.
2. **Customer Class**: Holds customer details (name and fidelity points) and provides accessors.
3. **Cart Class**: Manages a list of products, allowing addition of products and retrieval of all products.
4. **Promotion Interface**: Implemented using `std::function` to accept a `const DiscountStrategy&` and return a discount amount. The promotions (FIDELITY_PROMO, BULK_ITEM_PROMO, LARGE_ORDER_PROMO) are defined as constant lambda functions.
