    std::string currentSong;
    int volume;

public:
    MusicPlayer() : playlist(), currentSong(), volume(50) {}

    void addSong(const std::string& song) {
        playlist.push_back(song);
    }

    void removeSong(const std::string& song) {
        auto it = std::find(playlist.begin(), playlist.end(), song);
        if (it != playlist.end()) {
            playlist.erase(it);
            if (!currentSong.empty() && currentSong == song) {
                stop();
            }
        }
    }

    std::string play() {
        if (playlist.empty()) {
            return "";
        }
        if (!currentSong.empty()) {
            auto it = std::find(playlist.begin(), playlist.end(), currentSong);
            if (it != playlist.end()) {
                return currentSong;
            }
        }
        return playlist[0];
    }

    bool stop() {
        if (!currentSong.empty()) {
            currentSong.clear();
            return true;
        }
        return false;
    }

    bool switchSong() {
        if (currentSong.empty()) {
            return false;
        }
        auto it = std::find(playlist.begin(), playlist.end(), currentSong);
        if (it != playlist.end()) {
            size_t currentIndex = std::distance(playlist.begin(), it);
            if (currentIndex < playlist.size() - 1) {
                currentSong = playlist[currentIndex + 1];
                return true;
            }
        }
        return false;
    }

    bool previousSong() {
        if (currentSong.empty()) {
            return false;
        }
        auto it = std::find(playlist.begin(), playlist.end(), currentSong);
        if (it != playlist.end()) {
            size_t currentIndex = std::distance(playlist.begin(), it);
            if (currentIndex > 0) {
                currentSong = playlist[currentIndex - 1];
                return true;
            }
        }
        return false;
    }

    bool setVolume(int volume) {
        if (volume >= 0 && volume <= 100) {
            this->volume = volume;
            return true;
        }
        return false;
    }

