    return (P0 - Pe) / (1.0 - Pe);
}

double fleissKappa(const std::vector<std::vector<int>>& testData, int N, int k, int n) {
    if (N <= 0 || k <= 0 || n <= 0) {
        return 0.0;
    }
    std::vector<double> P(N, 0.0);
    int totalRatings = 0;

    for (int i = 0; i < N; ++i) {
        int rowSum = 0;
