        int value = 0;
        int num_aces = 0;
        for (const std::string& card : hand) {
            char rank = card[0];
            if (rank >= '2' && rank <= '9') {
                value += (rank - '0');
            } else if (rank == '1') {
                value += 10;
            } else if (rank == 'A') {
                value += 11;
                num_aces++;
            } else { // J, Q, K
                value += 10;
            }
