    }

    // Create a zip file from a list of files
    bool create_zip_file(const std::vector<std::string>& files, const std::string& output_file_name) {
        // Ensure output file has .zip extension
        if (output_file_name.find(".zip") == std::string::npos) {
            output_file_name += ".zip";
        }

        zip* zip_file = zip_open(output_file_name.c_str(), ZIP_CREATE | ZIP_TRUNCATE, nullptr);
        if (zip_file == nullptr) {
            return false;
        }

        for (const auto& file : files) {
            if (!fileExists(file)) {
                continue; // Skip if file doesn't exist
            }

            struct zip_stat zip_stat;
            if (zip_stat_name(zip_file, file.c_str(), &zip_stat) != ZIP_OK) {
                zip_close(zip_file);
                return false;
            }

            zip_int64_t error = zip_add(zip_file, file.c_str(), file.c_str());
            if (error != ZIP_OK) {
                zip_close(zip_file);
                return false;
            }
        }

        zip_close(zip_file);
        return true;
    }
};
```

### Key Notes:
1. **Library Usage**: The code uses the `libzip` library for zip operations. Ensure it's linked during compilation (e.g., `-lzip`).
2. **Error Handling**: Maintains Python's exception-like behavior by returning `false` on errors.
3. **Filesystem Operations**: Uses C++17's `<filesystem>` for directory creation and file existence checks.
4. **Memory Management**: Uses `std::unique_ptr` for RAII with `zip` handles.
5. **Edge Cases**: Handles missing files, invalid paths, and ensures output directories exist.

